   216
   217      // Allocate image.
   218      uchar *const image = reinterpret_cast<uchar*>(malloc(size));
   219      if (!image) {
   220          return false;
   221      }
   222
   223      bool valid = true;
   224
   225      if (info.rle) {
   226          // Decode image.
   227          char *dst = (char *)image;
   228          qint64 num = size;
   229
   230          while (num > 0) {
   231              if (s.atEnd()) {
   232                  valid = false;
   233                  break;
   234              }
   235
   236              // Get packet header.
   237              uchar c;
   238              s >> c;
   239
   240              uint count = (c & 0x7f) + 1;
   241              num -= count * pixel_size;
   242              if (num < 0) {
   243                  valid = false;
   244                  break;
   245              }
   246
   247              if (c & 0x80) {
   248                  // RLE pixels.
   249                  assert(pixel_size <= 8);
